def transform(grid):
    # Recolor 1-valued objects to the color of a geometrically identical exemplar.
    # The demo maps the 1 plus to the 8 plus; preserve unmatched objects.
    from collections import deque
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c] and (r,c) not in seen:
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
         y,x=q.pop(); cells.append((y,x))
         for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          yy,xx=y+dy,x+dx
          if 0<=yy<h and 0<=xx<w and grid[yy][xx]==grid[r][c] and (yy,xx) not in seen:
           seen.add((yy,xx)); q.append((yy,xx))
        comps.append((grid[r][c],cells))
    def shape(cells):
      a=min(y for y,x in cells); b=min(x for y,x in cells)
      return frozenset((y-a,x-b) for y,x in cells)
    refs={}
    for col,cells in comps:
      if col!=1: refs.setdefault(shape(cells),col)
    for col,cells in comps:
      if col==1 and shape(cells) in refs:
       for y,x in cells: out[y][x]=refs[shape(cells)]
    return out
