def transform(grid):
    # Match each 1-object by shape (allow rotations/reflections) to a colored exemplar.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c] and (r,c) not in seen:
        color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
         y,x=stack.pop(); cells.append((y,x))
         for dy in (-1,0,1):
          for dx in (-1,0,1):
           yy,xx=y+dy,x+dx
           if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
            seen.add((yy,xx)); stack.append((yy,xx))
        comps.append((color,cells))
    def variants(cells):
      pts=cells; result=[]
      for flip in (1,-1):
       for rot in range(4):
        q=[]
        for y,x in pts:
         a,b=y,flip*x
         for _ in range(rot): a,b=b,-a
         q.append((a,b))
        my=min(a for a,b in q); mx=min(b for a,b in q)
        result.append(frozenset((a-my,b-mx) for a,b in q))
      return result
    exemplars={}
    for col,cells in comps:
      if col!=1:
       for s in variants(cells): exemplars.setdefault(s,col)
    for col,cells in comps:
      if col==1:
       color=next((exemplars[s] for s in variants(cells) if s in exemplars),None)
       if color is not None:
        for y,x in cells: out[y][x]=color
    return out
